class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

class Solution:
    def removeNthFromEnd(self, head, n):
        values = []
        cur = head
        while cur:
            values.append(cur.val)
            cur = cur.next

        remove_index = len(values) - n
        dummy = ListNode()
        tail = dummy
        for i, value in enumerate(values):
            if i != remove_index:
                tail.next = ListNode(value)
                tail = tail.next
        return dummy.next

